={
  "model": "grok-4-fast",
  "messages": [
    { "role": "system", "content": "Kamu asisten AI 99Foods (toko makanan). Gunakan tools untuk query data / manipulasi data.\n\nTools:\n- get_omset_today: omset hari ini\n- get_omset_period(from, to): omset periode\n- get_profit_bersih(from, to): profit = omset - pembelian bahan\n- get_low_stock: menu dengan stok < 5\n- get_top_menu(period): top 5 menu terlaris\n- add_stock(menu_name, qty): tambah stok porsi\n- record_purchase(nama_bahan, jumlah, satuan, harga): catat pembelian\n- record_expense(keterangan, kategori, jumlah): catat pengeluaran\n- export_excel(from, to, type): file Excel\n- export_word(from, to): file Word\n\nJawab singkat, natural, Bahasa Indonesia, format Rp. Saat tidak perlu query, jawab langsung tanpa tool." },
    { "role": "user", "content": "={{ $json.message }}" }
  ],
  "tools": [
    { "type": "function", "function": { "name": "get_omset_today", "description": "Omset hari ini", "parameters": { "type": "object", "properties": {} } } },
    { "type": "function", "function": { "name": "get_omset_period", "description": "Omset periode", "parameters": { "type": "object", "properties": { "from": { "type": "string" }, "to": { "type": "string" } }, "required": ["from", "to"] } } },
    { "type": "function", "function": { "name": "get_profit_bersih", "description": "Profit bersih", "parameters": { "type": "object", "properties": { "from": { "type": "string" }, "to": { "type": "string" } }, "required": ["from", "to"] } } },
    { "type": "function", "function": { "name": "get_low_stock", "description": "Menu stok < 5", "parameters": { "type": "object", "properties": {} } } },
    { "type": "function", "function": { "name": "get_top_menu", "description": "Top 5 menu terlaris", "parameters": { "type": "object", "properties": { "period": { "type": "string" } }, "required": ["period"] } } },
    { "type": "function", "function": { "name": "add_stock", "description": "Tambah stok menu", "parameters": { "type": "object", "properties": { "menu_name": { "type": "string" }, "qty": { "type": "number" } }, "required": ["menu_name", "qty"] } } },
    { "type": "function", "function": { "name": "record_purchase", "description": "Catat pembelian", "parameters": { "type": "object", "properties": { "nama_bahan": { "type": "string" }, "jumlah": { "type": "number" }, "satuan": { "type": "string" }, "harga": { "type": "number" } }, "required": ["nama_bahan", "jumlah", "satuan", "harga"] } } },
    { "type": "function", "function": { "name": "record_expense", "description": "Catat pengeluaran", "parameters": { "type": "object", "properties": { "keterangan": { "type": "string" }, "kategori": { "type": "string" }, "jumlah": { "type": "number" } }, "required": ["keterangan", "kategori", "jumlah"] } } },
    { "type": "function", "function": { "name": "export_excel", "description": "Generate Excel", "parameters": { "type": "object", "properties": { "from": { "type": "string" }, "to": { "type": "string" }, "type": { "type": "string" } }, "required": ["from", "to", "type"] } } },
    { "type": "function", "function": { "name": "export_word", "description": "Generate Word", "parameters": { "type": "object", "properties": { "from": { "type": "string" }, "to": { "type": "string" } }, "required": ["from", "to"] } } }
  ],
  "tool_choice": "auto"
}

parameters.jsCode:
const data = items[0]?.json;
if (!data || !data.choices || !data.choices[0]) {
  return [{ json: { reply: 'Error: tidak ada respons dari Grok.', has_tools: false } }];
}
const msg = data.choices[0].message;
const tc = msg.tool_calls || [];
return [{
  json: {
    assistant_message: msg.content || '',
    has_tools: tc.length > 0 ? 'yes' : 'no',
    tool_name: tc.length > 0 ? tc[0].function.name : null,
    tool_args: tc.length > 0 ? JSON.parse(tc[0].function.arguments || '{}') : {},
    tool_call_id: tc.length > 0 ? tc[0].id : null,
    original_message: $('Webhook').first().json.message
  }
}];

const inData = items[0]?.json || {};
let str = '';
if (Array.isArray(inData)) {
  str = JSON.stringify(inData);
} else if (inData.profit_bersih !== undefined) {
  str = 'profit_bersih: ' + inData.profit_bersih;
} else if (inData.total_omset !== undefined) {
  str = 'total_omset: ' + inData.total_omset + ', jumlah_trx: ' + (inData.jumlah_trx || 0);
} else {
  str = JSON.stringify(inData);
}
const parse = $('Parse Grok').first().json;
return [{
  json: {
    tool_name: parse.tool_name,
    tool_args: parse.tool_args,
    tool_call_id: parse.tool_call_id,
    original_message: parse.original_message,
    tool_result: str
  }
}];

